"use client";

/* eslint-disable react-refresh/only-export-components */
// Exports both a component (PdfcnThemeProvider) and hooks/context intentionally.
// All PDF components import from a single file — splitting would break the public API.

import * as React from "react";
import { createContext, useContext } from "react";
import type { DependencyList, ReactNode } from "react";

import { theme as defaultTheme } from "./pdfcn-theme";

export type PdfcnTheme = typeof defaultTheme;

export const PdfcnThemeContext = createContext<PdfcnTheme>(defaultTheme);

export interface PdfcnThemeProviderProps {
  theme?: PdfcnTheme;
  children: ReactNode;
}

/**
 * Detect whether React currently has an active dispatcher.
 * When components are invoked as plain functions in tests, dispatcher is null.
 */
const hasActiveDispatcher = (): boolean => {
  const maybeInternals = React as unknown as {
    __CLIENT_INTERNALS_DO_NOT_USE_OR_WARN_USERS_THEY_CANNOT_UPGRADE?: {
      H?: unknown;
    };
  };

  const dispatcher =
    maybeInternals
      .__CLIENT_INTERNALS_DO_NOT_USE_OR_WARN_USERS_THEY_CANNOT_UPGRADE?.H;
  return dispatcher != null;
};

export const PdfcnThemeProvider = ({
  theme,
  children,
}: PdfcnThemeProviderProps) => (
  <PdfcnThemeContext.Provider value={theme ?? defaultTheme}>
    {children}
  </PdfcnThemeContext.Provider>
);

/**
 * Regex patterns that indicate a hook was called outside a valid React render tree.
 * These errors are caught and suppressed so components fall back to safe defaults.
 */
const HOOK_ERROR_PATTERNS =
  /invalid hook call|minified react error #321|useContext|useMemo|cannot read properties of null|dispatcher|renderWithHooks|resolveDispatcher|hooks can only be called|rendered fewer hooks/i;

/**
 * Calls a React hook with a graceful fallback for non-render environments (e.g. unit tests).
 * Uses hasActiveDispatcher() as the primary guard; the try/catch is a safety net for edge
 * cases where the dispatcher check passes but the hook still cannot execute.
 */
const callHook = <T,>(hook: () => T, fallback: T): T => {
  if (!hasActiveDispatcher()) {
    return fallback;
  }
  try {
    return hook();
  } catch (error) {
    if (error instanceof Error && HOOK_ERROR_PATTERNS.test(error.message)) {
      return fallback;
    }
    throw error;
  }
};

/**
 * Returns the active PdfcnTheme from context, or the default theme when called
 * outside a React render tree (e.g. unit tests).
 */
export const usePdfcnTheme = (): PdfcnTheme =>
  callHook(() => useContext(PdfcnThemeContext), defaultTheme);

/**
 * Calls factory() and returns the result.
 * The deps parameter is accepted for API compatibility with existing callers.
 */
// eslint-disable-next-line @typescript-eslint/no-unused-vars
export const useSafeMemo = <T,>(factory: () => T, _deps: DependencyList): T =>
  factory();

import type { ColorTokens } from "@/registry/themes";

/** Theme color token keys that can be used for the color prop */
export const THEME_COLOR_KEYS = [
  "foreground",
  "background",
  "muted",
  "mutedForeground",
  "primary",
  "primaryForeground",
  "border",
  "accent",
  "destructive",
  "success",
  "warning",
  "info",
] as const satisfies (keyof ColorTokens)[];

/** Resolves a color value: theme token key → hex, or raw CSS color as-is. */
export const resolveColor = (value: string, colors: ColorTokens): string => {
  const key = value as (typeof THEME_COLOR_KEYS)[number];
  return THEME_COLOR_KEYS.includes(key) ? colors[key] : value;
};

import type { ReactNode, ImgHTMLAttributes, AnchorHTMLAttributes } from "react";

export type Style = Record<string, unknown>;

export const StyleSheet = {
  create<T extends Record<string, Style>>(styles: T): T {
    return styles;
  },
};

type StyleInput = Style | Style[] | false | null | undefined;

interface ViewProps {
  children?: ReactNode;
  style?: StyleInput;
  className?: string;
  wrap?: boolean;
  fixed?: boolean;
  break?: boolean;
  minPresenceAhead?: number;
}

const flatten = (style?: StyleInput): Record<string, unknown> | undefined => {
  if (!style) {
    return undefined;
  }
  if (Array.isArray(style)) {
    return Object.assign({}, ...style.filter(Boolean));
  }
  return style;
};

export const View = ({ children, style, className, ...rest }: ViewProps) => {
  const {
    wrap: _w,
    fixed: _f,
    break: br,
    minPresenceAhead: _m,
    ...dom
  } = rest as ViewProps & Record<string, unknown>;
  const merged = flatten(style) ?? {};
  if (br) {
    Object.assign(merged, { breakBefore: "page" });
  }
  return (
    <div
      className={className}
      style={merged as React.CSSProperties}
      {...(dom as object)}
    >
      {children}
    </div>
  );
};

interface TextProps {
  children?: ReactNode;
  style?: StyleInput;
  className?: string;
  render?: (info: { pageNumber: number; totalPages: number }) => ReactNode;
  fixed?: boolean;
  href?: string;
  src?: string;
}

export const Text = ({
  children,
  style,
  className,
  render: _render,
  href,
  src,
  ...rest
}: TextProps) => {
  const merged = flatten(style) as React.CSSProperties | undefined;
  const link = href ?? src;
  if (link) {
    return (
      <a href={link} className={className} style={merged} {...(rest as object)}>
        {children}
      </a>
    );
  }
  return (
    <span className={className} style={merged} {...(rest as object)}>
      {children}
    </span>
  );
};

export const Image = ({
  src,
  style,
  ...rest
}: {
  src: string | { uri: string };
  style?: StyleInput;
} & Omit<ImgHTMLAttributes<HTMLImageElement>, "src" | "style">) => {
  const resolved = typeof src === "string" ? src : src.uri;
  return (
    <img
      src={resolved}
      style={flatten(style) as React.CSSProperties}
      alt=""
      {...rest}
    />
  );
};

export const Link = ({
  src,
  children,
  style,
  ...rest
}: {
  src: string;
  children?: ReactNode;
  style?: StyleInput;
} & Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "href" | "style">) => (
  <a href={src} style={flatten(style) as React.CSSProperties} {...rest}>
    {children}
  </a>
);

export const Document = ({
  children,
  title,
  style,
}: {
  children?: ReactNode;
  title?: string;
  style?: StyleInput;
}) => (
  <div data-pdf-document={title} style={flatten(style) as React.CSSProperties}>
    {children}
  </div>
);

export const Page = ({
  children,
  size: _size,
  style,
}: {
  children?: ReactNode;
  size?: string | { width: number; height: number };
  style?: StyleInput;
}) => (
  <div data-pdf-page style={flatten(style) as React.CSSProperties}>
    {children}
  </div>
);

import type { CSSProperties, ReactNode, SVGProps } from "react";

export const Svg = ({
  children,
  style,
  ...rest
}: SVGProps<SVGSVGElement> & { style?: CSSProperties }) => (
  <svg style={style} {...rest}>
    {children}
  </svg>
);

export const Rect = (props: SVGProps<SVGRectElement>) => <rect {...props} />;
export const Circle = (props: SVGProps<SVGCircleElement>) => (
  <circle {...props} />
);
export const G = (props: SVGProps<SVGGElement>) => <g {...props} />;
export const Line = (props: SVGProps<SVGLineElement>) => <line {...props} />;
export const Path = (props: SVGProps<SVGPathElement>) => <path {...props} />;
export const SvgText = ({
  children,
  style,
  ...rest
}: SVGProps<SVGTextElement> & {
  children?: ReactNode;
  style?: CSSProperties;
}) => (
  <text style={style} {...rest}>
    {children}
  </text>
);
